<?php
require __DIR__.'/../lib/bootstrap.php';require_admin();require_csrf();
try{$d=input();if(($d['action']??'')==='archive'){db()->prepare('UPDATE categories SET is_active=0 WHERE id=?')->execute([(int)$d['id']]);json_response(['ok'=>true]);}$id=(int)($d['id']??0);$name=trim($d['name']??'');if(!$name)json_response(['error'=>'El nombre es obligatorio'],422);$slug=trim($d['slug']??'')?:slugify($name);$v=[$name,$slug,$d['description']?:null,$d['seo_title']?:null,$d['seo_description']?:null,$d['geo_content']?:null,!empty($d['is_indexable']),!empty($d['is_active']),$d['sort_order']??0];if($id){$v[]=$id;db()->prepare('UPDATE categories SET name=?,slug=?,description=?,seo_title=?,seo_description=?,geo_content=?,is_indexable=?,is_active=?,sort_order=? WHERE id=?')->execute($v);}else{db()->prepare('INSERT INTO categories(name,slug,description,seo_title,seo_description,geo_content,is_indexable,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?,?)')->execute($v);$id=(int)db()->lastInsertId();}json_response(['ok'=>true,'id'=>$id]);}catch(Throwable $e){json_response(['error'=>'No fue posible guardar la categoría.'],422);}
